package com.fitnutri.backend.submission;
import com.fitnutri.backend.common.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.records.food.*;
import com.fitnutri.backend.support.PostgresIntegrationSupport;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
class SubmissionV2IT extends PostgresIntegrationSupport {
 @Autowired SubmissionService service;@Autowired CanonicalEntryHasherV2 hasher;@Autowired UserRepository users;@Autowired FoodRecordRepository foods;@Autowired SubmissionReceiptRepository receipts;@Autowired PlatformTransactionManager manager;
 User owner(){var u=new User();u.setEmail("v2-proof-"+UUID.randomUUID()+"@example.test");u.setDisplayName("Synthetic proof test");u.setPasswordHash("synthetic-only");return users.saveAndFlush(u);}
 FoodEntryInputs.BatchRequest request(UUID submission,UUID entry,String grams){return new FoodEntryInputs.BatchRequest(submission,LocalDate.of(2020,1,1),"Australia/Sydney",RecordSource.MANUAL,List.of(new FoodEntryInputs.Single(entry,"101",new BigDecimal(grams),MealType.LUNCH,null,null)),"f".repeat(64));}
 // Infrastructure proof fixture is honest legacy data, not a fabricated verified source or a new-business creation test.
 SubmissionReceiptV2Response.Proof create(User owner,UUID entry){var row=new FoodRecord();row.setUser(owner);row.setFoodName("PRIVATE_SYNTHETIC_PROOF_SENTINEL");row.setQuantityGramsSnapshot(new BigDecimal("100"));row.setMealType(MealType.LUNCH);row.setSource(RecordSource.MANUAL);row.setRecordedAt(Instant.parse("2020-01-01T00:00:00Z"));row.setRecordDate(LocalDate.of(2020,1,1));row.setClientEntryId(entry);row=foods.saveAndFlush(row);return new SubmissionReceiptV2Response.Proof(2,List.of(new SubmissionReceiptV2Response.Root("SINGLE",row.getId().toString(),entry,row.getRecordDate(),0)),List.of(new SubmissionReceiptV2Response.Leaf("FOOD_COMPONENT",row.getId().toString(),entry,entry,row.getRecordDate(),0)));}
 @Test void retryAndConcurrentDuplicateCreateOneCommittedMinimalProof()throws Exception{var owner=owner();var entry=UUID.randomUUID();var input=hasher.food(request(UUID.randomUUID(),entry,"100"));var start=new CountDownLatch(1);var writes=new AtomicInteger();try(var pool=Executors.newFixedThreadPool(2)){Callable<SubmissionReceiptV2Response> work=()->{start.await();return service.withSubmissionV2(owner.getId(),input,u->{writes.incrementAndGet();return create(u,entry);});};var a=pool.submit(work);var b=pool.submit(work);start.countDown();var first=a.get(20,TimeUnit.SECONDS);var second=b.get(20,TimeUnit.SECONDS);assertNotEquals(first.replayed(),second.replayed());assertEquals(first.roots(),second.roots());assertEquals(first.leaves(),second.leaves());assertEquals(1,writes.get());assertEquals(1,foods.findByUserIdOrderByRecordedAtDesc(owner.getId()).size());var stored=receipts.findByUserIdAndSubmissionId(owner.getId(),input.submissionId()).orElseThrow();assertEquals(Set.of("schemaVersion","roots","leaves"),stored.getResultJson().keySet());assertFalse(stored.getResultJson().toString().contains("PRIVATE"));assertEquals(first.roots(),service.findReceiptV2(owner.getId(),input.submissionId()).roots());assertThrows(BusinessException.class,()->service.findReceiptV2(owner().getId(),input.submissionId()));assertThrows(BusinessException.class,()->service.findReceipt(owner.getId(),input.submissionId()));}}
 @Test void changedInputConflictsAndSoftDeletionCannotCreateAgainOrResurrect(){var owner=owner();var entry=UUID.randomUUID();var request=request(UUID.randomUUID(),entry,"100");var input=hasher.food(request);var first=service.withSubmissionV2(owner.getId(),input,u->create(u,entry));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmissionV2(owner.getId(),hasher.food(request(input.submissionId(),entry,"101")),u->{fail("changed content must not execute");return null;})).code());var row=foods.findById(Long.valueOf(first.roots().getFirst().id())).orElseThrow();row.setDeletedAt(Instant.now());foods.saveAndFlush(row);assertTrue(service.withSubmissionV2(owner.getId(),input,u->{fail("replay never checks current business inputs or creates");return null;}).replayed());assertEquals("CLIENT_ENTRY_CONFLICT",assertThrows(BusinessException.class,()->service.withSubmissionV2(owner.getId(),hasher.food(request(UUID.randomUUID(),entry,"100")),u->{fail("deleted identity remains reserved");return null;})).code());assertTrue(foods.findByUserIdOrderByRecordedAtDesc(owner.getId()).isEmpty());}
 @Test void missingOrExtraProofRollsBackCallbackAndReceipt(){var owner=owner();var entry=UUID.randomUUID();var input=hasher.food(request(UUID.randomUUID(),entry,"100"));assertThrows(IllegalStateException.class,()->service.withSubmissionV2(owner.getId(),input,u->{var proof=create(u,entry);return new SubmissionReceiptV2Response.Proof(2,proof.roots(),List.of());}));assertTrue(foods.findByUserIdOrderByRecordedAtDesc(owner.getId()).isEmpty());assertTrue(receipts.findByUserIdAndSubmissionId(owner.getId(),input.submissionId()).isEmpty());assertThrows(IllegalStateException.class,()->new TransactionTemplate(manager).execute(status->service.withSubmissionV2(owner.getId(),input,u->create(u,entry))));}
}
